/**
 * Backend used when the tablet has no server saved yet.
 * Change it on the device in Server settings (long-press the PMS+ logo on the sign-in screen).
 * 10.0.2.2 is the dev PC's localhost as seen from the Android emulator.
 */
export const DEFAULT_API_URL = 'http://10.0.2.2:8000/api/';

/** Trims, checks the scheme and adds the trailing slash axios needs to join `auth/login/`. */
export function normalizeApiUrl(input: string): string | null {
  const url = input.trim();
  if (!/^https?:\/\/[^\s/]+/i.test(url)) return null;
  return url.endsWith('/') ? url : `${url}/`;
}

