import axios from 'axios';

/** Member as returned by `auth/login/` (`data`) and `auth/current-member/`. */
export type Member = {
  id: number;
  emp_id: string | null;
  username: string;
  name: string | null;
  role_level: number;
  role_level_display: string;
  production_area_names: string[];
  has_all_areas: boolean;
};

export const api = axios.create({ timeout: 15000 });

export function configureApi(baseURL: string, token: string | null) {
  api.defaults.baseURL = baseURL;
  if (token) {
    api.defaults.headers.common.Authorization = `Token ${token}`;
  } else {
    delete api.defaults.headers.common.Authorization;
  }
}

let onUnauthorized: (() => void) | null = null;

/** Called when the backend rejects the saved token (e.g. the member logged out on the web). */
export function setUnauthorizedHandler(handler: (() => void) | null) {
  onUnauthorized = handler;
}

api.interceptors.response.use(undefined, (error) => {
  if (axios.isAxiosError(error) && error.response?.status === 401) onUnauthorized?.();
  return Promise.reject(error);
});

