    const url = normalizeApiUrl(input);
    if (!url) return setStatus({ ok: false, text: 'Enter a URL starting with http:// or https://' });
    await setServerUrl(url);
    router.back();
  }

  return (
    <SafeAreaView style={styles.screen}>
      <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
        <Text style={styles.title}>Server settings</Text>
        <Text style={styles.hint}>
          Backend API address, ending in /api/. Emulator: {DEFAULT_API_URL} · Tablet on the dev PC:
          http://&lt;PC IP&gt;:8000/api/
        </Text>
        <PmsTextField
          label="API URL"
          value={input}
          onChangeText={(t) => {
            setInput(t);
            setStatus(null);
          }}
          autoCapitalize="none"
          autoCorrect={false}
          keyboardType="url"
        />
        {status && <Text style={[styles.status, { color: status.ok ? PmsColors.onTime : PmsColors.danger }]}>{status.text}</Text>}
        <View style={styles.row}>
          <PmsButton title="Test connection" variant="secondary" onPress={test} loading={busy} style={styles.flex} />
          <PmsButton title="Save" onPress={saveUrl} style={styles.flex} />
        </View>
        <View style={styles.row}>
          <PmsButton title="Use default" variant="secondary" onPress={() => setInput(DEFAULT_API_URL)} style={styles.flex} />
          <PmsButton title="Cancel" variant="secondary" onPress={() => router.back()} style={styles.flex} />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
  content: { padding: PmsSizes.pad, gap: PmsSizes.gap, width: '100%', maxWidth: 720, alignSelf: 'center' },
  title: { fontSize: 32, fontWeight: '700', color: PmsColors.text },
  hint: { fontSize: 16, color: PmsColors.textSecondary },
  status: { fontSize: 16, fontWeight: '600' },
  row: { flexDirection: 'row', gap: PmsSizes.gap },
  flex: { flex: 1 },
});

