def get_serializer_class(self):
    if self.action == 'pm_summary':
        return EquipmentScheduleSummarySerializer
    if self.action == 'list':
        return EquipmentListSerializer
    if self.action in ('create', 'update', 'partial_update'):
        return EquipmentWriteSerializer
    return EquipmentDetailSerializer

def perform_create(self, serializer):
    serializer.save(created_by=self.request.user, updated_by=self.request.user)

def perform_update(self, serializer):
    serializer.save(updated_by=self.request.user)

@action(detail=False, methods=['post'], url_path='preview-number')
def preview_number(self, request):
    serializer = EquipmentNumberPreviewSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    try:
        number = preview_equipment_number(
            serializer.validated_data['equipment_model'],
            serializer.validated_data['prod_area_prefix'],
        )
    except DjangoValidationError as exc:
        return Response(getattr(exc, 'message_dict', None) or {'detail': exc.messages}, status=status.HTTP_400_BAD_REQUEST)
    return Response({'equipment_number': number})

@action(detail=False, methods=['get'], url_path='pm-summary')
def pm_summary(self, request):
    qs = self.get_queryset()
    serializer = EquipmentScheduleSummarySerializer(qs, many=True, context={'request': request})
    return Response(serializer.data)

@action(detail=True, methods=['get'], url_path='esd-source')
def esd_source(self, request, equipment_number=None):
    equipment = self.get_object()
    result = resolve_esd_source(equipment)
    if not result.ok:
        return Response(
            {'code': result.code, 'detail': result.message},
            status=status.HTTP_400_BAD_REQUEST,
        )
    return Response(result.data)

@action(detail=True, methods=['get', 'post'], url_path='esd')
def esd(self, request, equipment_number=None):
    """GET: the spec this equipment is measured against + its latest reading. POST: record a reading."""
