/** DD/MM/YYYY, the format printed on the ESD label. */
export function formatDate(iso: string | null | undefined): string {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  const dd = String(d.getDate()).padStart(2, "0");
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  return `${dd}/${mm}/${d.getFullYear()}`;
}

/** ESD readings span decades (1e5–1e11 Ω): large values in scientific notation, e.g. 5.0e+7. */
export function formatReading(value: number | null | undefined, unit?: string | null): string {
  if (value == null) return "—";
  const text = Math.abs(value) >= 10000 ? value.toExponential(1) : String(value);
  return unit ? `${text} ${unit}` : text;
}

