import type { PeriodSummary } from "@/lib/equipment";

/** `GET equipments/<number>/profile/` */
export type EquipmentProfile = {
  equipment_number: string;
  model: string | null;
  part_number: string | null;
  is_esd: boolean;
  category: { id: number; name: string; production_area: string | null } | null;
  periods: (Omit<PeriodSummary, "schedule_id" | "custom_period_name"> & {
    pending_record_id: string | null;
  })[];
};

export type EsdSpec = {
  id: number;
  name: string;
  min_value: number | null;
  max_value: number | null;
  unit: string;
  spec_label: string;
};

/** Latest measurement, in the ESD label's field names. */
export type EsdReading = {
  esdValue: number;
  esdUnit: string;
  result: "PASS" | "FAIL";
  measuredDate: string;
  measuredBy: string;
};

/** `GET equipments/<number>/esd/` */
export type EsdInfo = { spec: EsdSpec; latest: EsdReading | null };

export type PmRecordStatus = "submitted" | "approved" | "rejected";

/** `GET pm-records/?equipment_number=<n>` (not paginated, newest first). */
export type PmRecordSummary = {
  id: string;
  period_name: string;
  performed_at: string;
  performed_by_name: string | null;
  status: PmRecordStatus;
  is_passed: boolean | null;
  approval_bypassed: boolean;
  source: string;
};

export async function fetchProfile(number: string): Promise<EquipmentProfile> {
  const { data } = await api.get<EquipmentProfile>(`equipments/${encodeURIComponent(number)}/profile/`);
  return data;
}

/** Null when the equipment has no ESD spec (400 `NO_ESD_SPEC`). */
export async function fetchEsd(number: string): Promise<EsdInfo | null> {
  try {
    const { data } = await api.get<EsdInfo>(`equipments/${encodeURIComponent(number)}/esd/`);
    return data;
  } catch (e) {
    if (isAxiosError(e) && (e.response?.data as { code?: string } | undefined)?.code === "NO_ESD_SPEC") {
      return null;
    }
    throw e;
  }
}

export async function fetchPmRecords(number: string): Promise<PmRecordSummary[]> {
  const { data } = await api.get<PmRecordSummary[]>("pm-records/", {
    params: { equipment_number: number },
  });
  return data;
}

export type EquipmentDetail = {
  profile: EquipmentProfile;
  esd: EsdInfo | null;
  records: PmRecordSummary[];
};

export async function fetchEquipmentDetail(number: string): Promise<EquipmentDetail> {
  const [profile, records] = await Promise.all([fetchProfile(number), fetchPmRecords(number)]);
  const esd = profile.is_esd ? await fetchEsd(number) : null;
  return { profile, esd, records };
}

