import { router, useFocusEffect, useLocalSearchParams } from "expo-router";
import { useCallback, useState, type ReactNode } from "react";
import { ActivityIndicator, Alert, RefreshControl, ScrollView, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { STATUS_STYLE } from "@/components/pms/equipment-card";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { errorMessage } from "@/lib/api";
import { periodLabel, periodStatus } from "@/lib/equipment";
import {
  fetchEquipmentDetail,
  type EquipmentDetail,
  type EquipmentProfile,
  type EsdInfo,
  type PmRecordStatus,
  type PmRecordSummary,
} from "@/lib/equipment-detail";
import { formatDate, formatReading } from "@/lib/format";

const RECENT_RECORDS = 5;

const RECORD_STATUS: Record<PmRecordStatus, { color: string; label: string }> = {
  submitted: { color: PmsColors.pending, label: "Waiting approval" },
  approved: { color: PmsColors.onTime, label: "Approved" },
  rejected: { color: PmsColors.overdue, label: "Rejected" },
};

// Perform PM and Measure ESD screens are the next steps.
function comingNext(what: string) {
  Alert.alert(what, "This screen is coming in the next step.");
}

export default function EquipmentDetailScreen() {
  const { number } = useLocalSearchParams<{ number: string }>();
  const [detail, setDetail] = useState<EquipmentDetail | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(
    () =>
      fetchEquipmentDetail(number).then(
        (data) => {
          setDetail(data);
          setError(null);
        },
        (e) => setError(errorMessage(e)),
      ),
    [number],
  );

  // Reload whenever the screen comes back into view, e.g. after submitting a PM.
  useFocusEffect(
    useCallback(() => {
      load();
    }, [load]),
  );

  async function refresh() {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }

  return (
    <SafeAreaView style={styles.screen} edges={["top", "left", "right"]}>
      <View style={styles.bar}>
        <PmsButton title="‹ Back" variant="secondary" onPress={() => router.back()} />
        <View style={styles.flex}>
          <Text style={styles.title} numberOfLines={1}>
            {number}
          </Text>
          {detail && (
            <Text style={styles.subtitle} numberOfLines={1}>
              {[detail.profile.model, detail.profile.part_number, detail.profile.category?.name]
                .filter(Boolean)
                .join(" · ")}
            </Text>
          )}
        </View>
      </View>

      {detail === null ? (
        <View style={styles.center}>
          {error ? (
            <>
              <Text style={styles.error}>{error}</Text>
              <PmsButton title="Retry" onPress={refresh} loading={refreshing} />
            </>
          ) : (
            <ActivityIndicator size="large" color={PmsColors.primary} />
          )}
        </View>
      ) : (
        <ScrollView
          contentContainerStyle={styles.content}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} colors={[PmsColors.primary]} />}>
          {error && <Text style={styles.error}>{error}</Text>}
          <View style={styles.columns}>
            <View style={styles.main}>
              <PmSchedule periods={detail.profile.periods} />
            </View>
            <View style={styles.side}>
              {detail.esd && <EsdCard esd={detail.esd} />}
              <RecentPm records={detail.records} />
            </View>
          </View>
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

function Card({ title, accent, children }: { title: string; accent?: string; children: ReactNode }) {
  return (
    <View style={[styles.card, accent ? { borderTopColor: accent, borderTopWidth: 6 } : null]}>
      <Text style={styles.cardTitle}>{title}</Text>
      {children}
    </View>
  );
}

function PmSchedule({ periods }: { periods: EquipmentProfile["periods"] }) {
  if (periods.length === 0) {
    return (
      <Card title="PM schedule">
        <Text style={styles.muted}>No PM checklist is set for this equipment.</Text>
      </Card>
    );
  }
  return (
    <Card title="PM schedule">
      {periods.map((p) => {
        const s = STATUS_STYLE[periodStatus(p)];
        return (
          <View key={p.pm_period} style={styles.period}>
            <View style={styles.periodHead}>
              <Text style={styles.periodName}>{periodLabel(p)}</Text>
              <View style={[styles.pill, { borderColor: s.color }]}>
                <Text style={[styles.pillText, { color: s.color }]}>{s.label}</Text>
              </View>
            </View>
            <View style={styles.periodDates}>
              <Field label="Last PM" value={formatDate(p.last_pm_date)} />
              <Field label="Next PM" value={formatDate(p.next_pm_date)} />
              <Field
                label={p.is_overdue ? "Overdue" : "Due in"}
                value={p.days_until_due == null ? "—" : `${Math.abs(p.days_until_due)} days`}
                color={p.is_overdue ? PmsColors.overdue : undefined}
              />
            </View>
            {/* Same rule as the web: one PM per period may wait for approval at a time. */}
            {p.pending_approval ? (
              <Text style={styles.waiting}>
                PM waiting for approval{p.pending_approval_step ? ` · ${p.pending_approval_step}` : ""}
              </Text>
            ) : (
              <PmsButton title={`Perform ${periodLabel(p)} PM`} onPress={() => comingNext("Perform PM")} />
            )}
          </View>
        );
      })}
    </Card>
  );
}

function EsdCard({ esd }: { esd: EsdInfo }) {
  const latest = esd.latest;
  const passColor = latest?.result === "PASS" ? PmsColors.onTime : PmsColors.overdue;
  return (
    <Card title="ESD" accent={PmsColors.esd}>
      <Field label="Spec" value={esd.spec.spec_label || esd.spec.name} />
      {latest ? (
        <>
          <View style={styles.esdRow}>
            <Text style={styles.esdValue}>{formatReading(latest.esdValue, latest.esdUnit)}</Text>
            <View style={[styles.pill, { borderColor: passColor }]}>
              <Text style={[styles.pillText, { color: passColor }]}>{latest.result}</Text>
            </View>
          </View>
          <Text style={styles.muted}>
            Measured {formatDate(latest.measuredDate)} by {latest.measuredBy || "—"}
          </Text>
        </>
      ) : (
        <Text style={styles.muted}>Not measured yet.</Text>
      )}
      <PmsButton title="Measure ESD" onPress={() => comingNext("Measure ESD")} style={styles.esdButton} />
    </Card>
  );
}

function RecentPm({ records }: { records: PmRecordSummary[] }) {
  const recent = records.slice(0, RECENT_RECORDS);
  return (
    <Card title="Recent PM">
      {recent.length === 0 && <Text style={styles.muted}>No PM recorded yet.</Text>}
      {recent.map((r) => {
        const s = RECORD_STATUS[r.status] ?? { color: PmsColors.textSecondary, label: r.status };
        return (
          <View key={r.id} style={styles.record}>
            <View style={styles.flex}>
              <Text style={styles.recordTitle}>
                {formatDate(r.performed_at)} · {r.period_name}
              </Text>
              <Text style={styles.muted} numberOfLines={1}>
                {r.performed_by_name ?? "—"}
                {r.is_passed === false ? " · has failed steps" : ""}
              </Text>
            </View>
            <Text style={[styles.recordStatus, { color: s.color }]}>
              {r.approval_bypassed ? "Bypassed" : s.label}
            </Text>
          </View>
        );
      })}
    </Card>
  );
}

function Field({ label, value, color }: { label: string; value: string; color?: string }) {
  return (
    <View style={styles.field}>
      <Text style={styles.fieldLabel}>{label}</Text>
      <Text style={[styles.fieldValue, color ? { color } : null]}>{value}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
  flex: { flex: 1 },
  bar: {
    flexDirection: "row",
    alignItems: "center",
    gap: PmsSizes.gap,
    padding: PmsSizes.gap,
    paddingHorizontal: PmsSizes.pad,
    backgroundColor: PmsColors.surface,
    borderBottomWidth: 1,
    borderBottomColor: PmsColors.border,
  },
  title: { fontSize: 24, fontWeight: "700", color: PmsColors.text },
  subtitle: { fontSize: 16, color: PmsColors.textSecondary },
  center: { flex: 1, alignItems: "center", justifyContent: "center", gap: PmsSizes.gap, padding: PmsSizes.pad },
  error: { fontSize: 16, color: PmsColors.danger, textAlign: "center" },
  content: { padding: PmsSizes.pad, gap: PmsSizes.gap },
  // Side by side on a landscape tablet; wraps to one column when the screen is too narrow.
  columns: { flexDirection: "row", flexWrap: "wrap", gap: PmsSizes.gap, alignItems: "flex-start" },
  main: { flexGrow: 3, flexBasis: 420, gap: PmsSizes.gap },
  side: { flexGrow: 2, flexBasis: 320, gap: PmsSizes.gap },
  card: {
    backgroundColor: PmsColors.surface,
    borderRadius: PmsSizes.radius,
    borderWidth: 1,
    borderColor: PmsColors.border,
    padding: PmsSizes.gap + 4,
    gap: 12,
  },
  cardTitle: { fontSize: 20, fontWeight: "700", color: PmsColors.text },
  muted: { fontSize: 15, color: PmsColors.textSecondary },
  period: { gap: 10, paddingTop: 12, borderTopWidth: 1, borderTopColor: PmsColors.border },
  periodHead: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 8 },
  periodName: { fontSize: 18, fontWeight: "700", color: PmsColors.text },
  periodDates: { flexDirection: "row", gap: PmsSizes.pad },
  pill: { borderWidth: 2, borderRadius: 999, paddingHorizontal: 12, paddingVertical: 2 },
  pillText: { fontSize: 14, fontWeight: "700" },
  waiting: { fontSize: 16, fontWeight: "600", color: PmsColors.pending, paddingVertical: 8 },
  field: { gap: 2 },
  fieldLabel: { fontSize: 13, color: PmsColors.textSecondary },
  fieldValue: { fontSize: 17, fontWeight: "600", color: PmsColors.text },
  esdRow: { flexDirection: "row", alignItems: "center", gap: 12 },
  esdValue: { fontSize: 28, fontWeight: "800", color: PmsColors.text },
  esdButton: { backgroundColor: PmsColors.esd },
  record: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    paddingTop: 10,
    borderTopWidth: 1,
    borderTopColor: PmsColors.border,
  },
  recordTitle: { fontSize: 16, fontWeight: "600", color: PmsColors.text },
  recordStatus: { fontSize: 15, fontWeight: "700" },
});

