71	export function equipmentStatus(e: EquipmentSummary): {
72	  status: PmStatus;
73	  period: PeriodSummary | null;
74	} {
75	  let worst: { status: PmStatus; period: PeriodSummary | null } = {
76	    status: "new",
77	    period: null,
78	  };
79	  for (const p of e.periods) {
80	    const s = periodStatus(p);
81	    if (worst.period === null || STATUS_RANK[s] < STATUS_RANK[worst.status])
82	      worst = { status: s, period: p };
83	  }
