class PmRecordCreateSerializer(serializers.ModelSerializer):
    sop_records = PmRecordSopInputSerializer(many=True, write_only=True)

    class Meta:
        model = PmRecord
        fields = ['equipment', 'pm_period', 'performed_at', 'notes', 'sop_records']

    def validate(self, data):
        equipment = data.get('equipment')
        pm_period = data.get('pm_period')
        if equipment:
            assert_area_allowed(request_user(self), equipment.production_area_id)
        if equipment and pm_period:
            equipment_checklist_id = equipment.equipment_model.pm_checklist_id if equipment.equipment_model_id else None
            if equipment_checklist_id != pm_period.pm_checklist_id:
                raise serializers.ValidationError({
                    'pm_period': "The selected period does not belong to this equipment's PM checklist."
                })
        sop_records = data.get('sop_records', [])
        expected_sop_ids = set(pm_period.sops.values_list('id', flat=True))
        submitted_sop_ids = {item['pm_sop'].id for item in sop_records}
        missing = expected_sop_ids - submitted_sop_ids
        if missing:
            raise serializers.ValidationError({
                'sop_records': f"Missing {len(missing)} SOP(s). All SOPs must be completed."
            })
        extra = submitted_sop_ids - expected_sop_ids
        if extra:
            raise serializers.ValidationError({
                'sop_records': "Contains SOPs that don't belong to this period."
            })
        if PmRecord.objects.filter(
            equipment=equipment, pm_period=pm_period, status=PmRecord.STATUS_SUBMITTED,
        ).exists():
            raise serializers.ValidationError({
                'pm_period': 'A PM for this period is still waiting for approval.'
            })
        return data

    def create(self, validated_data):
        sop_records_data = validated_data.pop('sop_records')
        equipment = validated_data['equipment']
        return create_pm_record(
            equipment=equipment,
            pm_period=validated_data['pm_period'],
            performed_at=validated_data['performed_at'],
            performed_by=self.context['request'].user,
            sop_items=sop_records_data,
            notes=validated_data.get('notes'),
            source=PmRecord.SOURCE_WEB,
            auto_approve=resolve_auto_approve(equipment, PmRecord.SOURCE_WEB),
        )

class EsdMeasurementSerializer(serializers.ModelSerializer):
    equipment_number = serializers.CharField(source='equipment.equipment_number', read_only=True)

class PmSopViewSet(ProdAreaFilterMixin, BaseViewSet):
    serializer_class = PmSopSerializer
    filter_backends = [filters.OrderingFilter]
    ordering = ['order']
    prod_area_path = 'pm_period__pm_checklist__production_area__name'

    def get_queryset(self):
        qs = PmSop.objects.select_related('pm_period')
        pm_period = self.request.query_params.get('pm_period')
        if pm_period:
            qs = qs.filter(pm_period_id=pm_period)
        return self.filter_prod_area(qs)

    def perform_create(self, serializer):
        serializer.save(created_by=self.request.user, updated_by=self.request.user)

    def perform_update(self, serializer):
        serializer.save(updated_by=self.request.user)

def create(self, request, *args, **kwargs):
    sop_records_raw = request.data.get('sop_records', '[]')
    try:
        sop_records = json.loads(sop_records_raw) if isinstance(sop_records_raw, str) else sop_records_raw
    except (json.JSONDecodeError, TypeError):
        sop_records = []

    for item in sop_records:
        key = f"image_{item.get('pm_sop', '')}"
        if key in request.FILES:
            item['image'] = request.FILES[key]

    data = request.data.dict() if hasattr(request.data, 'dict') else dict(request.data)
    data['sop_records'] = sop_records

    serializer = PmRecordCreateSerializer(data=data, context={'request': request})
    serializer.is_valid(raise_exception=True)
    pm_record = serializer.save()
    return Response(PmRecordSerializer(pm_record).data, status=status.HTTP_201_CREATED)

@action(detail=True, methods=['post'])
def act(self, request, pk=None):
    record = self.get_object()

    if record.status != PmRecord.STATUS_SUBMITTED:
        return Response({'detail': 'Only submitted records can be acted on.'}, status=status.HTTP_400_BAD_REQUEST)

    step = record.current_workflow_step
    if not step:
        return Response({'detail': 'No workflow step assigned to this record.'}, status=status.HTTP_400_BAD_REQUEST)

    assignee_ids = list(step.assignments.values_list('member_id', flat=True))
    if request.user.pk not in assignee_ids and request.user.role_level != RoleLevel.ADMINISTRATOR:
        return Response({'detail': 'You are not assigned to this approval step.'}, status=status.HTTP_403_FORBIDDEN)

    if PmRecordApproval.objects.filter(pm_record=record, step=step, approver=request.user).exists():
        return Response({'detail': 'You have already acted on this step.'}, status=status.HTTP_400_BAD_REQUEST)

    serializer = PmRecordActSerializer(data=request.data)

