import { api } from "@/lib/api";

/** One checklist step, from `GET pm-sops/?pm_period=<id>`. */
export type PmSop = {
  id: number;
  order: number;
  name: string;
  description: string | null;
  input_type: "checkbox" | "number_range" | "text";
  min_value: number | null;
  max_value: number | null;
  unit: string | null;
  requires_image: boolean;
};

export async function fetchSops(pmPeriod: number, area: string): Promise<PmSop[]> {
  const { data } = await api.get<PmSop[]>("pm-sops/", {
    params: { pm_period: pmPeriod, prod_area_name: area },
  });
  return [...data].sort((a, b) => a.order - b.order);
}

/** What the technician entered for one step. `number` stays text so "1." can be typed. */
export type StepAnswer = {
  ok: boolean | null;
  number: string;
  text: string;
  photoUri: string | null;
};

export const EMPTY_ANSWER: StepAnswer = { ok: null, number: "", text: "", photoUri: null };

export function parseNumber(input: string): number | null {
  const trimmed = input.trim().replace(",", ".");
  if (trimmed === "") return null;
  const value = Number(trimmed);
  return Number.isFinite(value) ? value : null;
}

/** Same rule as `PmRecordSop.save()` on the backend. */
export function numberPasses(sop: PmSop, value: number): boolean {
  return (sop.min_value == null || value >= sop.min_value) && (sop.max_value == null || value <= sop.max_value);
}

/** The backend refuses a PM unless every step has a result (and a photo where required). */
export function isStepDone(sop: PmSop, answer: StepAnswer): boolean {
  if (sop.requires_image && !answer.photoUri) return false;
  if (sop.input_type === "checkbox") return answer.ok !== null;
  if (sop.input_type === "number_range") return parseNumber(answer.number) !== null;
  return answer.text.trim() !== "";
}

/** `POST pm-records/` response, only the fields the result screen shows. */
export type SubmittedPm = {
  id: string;
  status: "submitted" | "approved" | "rejected";
  is_passed: boolean | null;
  approval_bypassed: boolean;
  current_workflow_step: { name: string } | null;
};

type SubmitInput = {
  equipmentId: string;
  pmPeriod: number;
  notes: string;
  sops: PmSop[];
  answers: Record<number, StepAnswer>;
};

/** Multipart: results as a JSON string, one photo per step as file field `image_<pm_sop id>`. */
export async function submitPm({ equipmentId, pmPeriod, notes, sops, answers }: SubmitInput): Promise<SubmittedPm> {
  const form = new FormData();
  form.append("equipment", equipmentId);
  form.append("pm_period", String(pmPeriod));
  form.append("performed_at", new Date().toISOString());
  form.append("notes", notes);

  const sopRecords = sops.map((sop) => {
    const a = answers[sop.id] ?? EMPTY_ANSWER;
    return {
      pm_sop: sop.id,
      result_boolean: sop.input_type === "checkbox" ? a.ok : null,
      result_number: sop.input_type === "number_range" ? parseNumber(a.number) : null,
      result_text: sop.input_type === "text" ? a.text.trim() : null,
      notes: null,
    };
  });
  form.append("sop_records", JSON.stringify(sopRecords));

  for (const sop of sops) {
    const uri = answers[sop.id]?.photoUri;
    // React Native's FormData takes a {uri, name, type} object for files.
    if (uri) form.append(`image_${sop.id}`, { uri, name: `step-${sop.id}.jpg`, type: "image/jpeg" } as never);
  }

  const { data } = await api.post<SubmittedPm>("pm-records/", form, {
    headers: { "Content-Type": "multipart/form-data" },
    timeout: 120000, // photos over factory Wi-Fi
  });
  return data;
}

