38	export const WARNING_DAYS = 7;
39	
40	export type PmStatus = "overdue" | "due" | "new" | "pending" | "on_time";
41	
42	export const STATUS_RANK: Record<PmStatus, number> = {
43	  overdue: 0,
44	  due: 1,
45	  new: 2,
46	  pending: 3,
47	  on_time: 4,
48	};
49	
50	/** The fields both `pm-summary` and `profile` return for a period. */
51	export type PeriodStatusFields = Pick<
52	  PeriodSummary,
53	  "is_overdue" | "days_until_due" | "pending_approval" | "last_pm_date"
54	>;
55	
56	export function periodStatus(p: PeriodStatusFields): PmStatus {
57	  if (p.is_overdue) return "overdue";
58	  if (p.days_until_due != null && p.days_until_due <= WARNING_DAYS)
59	    return "due";
60	  if (p.days_until_due != null) return "on_time";
61	  if (p.pending_approval && p.last_pm_date === null) return "pending";
62	  return "new";
63	}
64	
65	export function periodLabel(
66	  p: Pick<PeriodSummary, "period_name"> & { custom_period_name?: string | null },
67	): string {
68	  return p.custom_period_name || p.period_name;
69	}
70	
71	export function equipmentStatus(e: EquipmentSummary): {
72	  status: PmStatus;
73	  period: PeriodSummary | null;
74	} {
75	  let worst: { status: PmStatus; period: PeriodSummary | null } = {
76	    status: "new",
77	    period: null,
78	  };
79	  for (const p of e.periods) {
80	    const s = periodStatus(p);
81	    if (worst.period === null || STATUS_RANK[s] < STATUS_RANK[worst.status])
82	      worst = { status: s, period: p };
83	  }
84	  return worst;
85	}

