71	export async function submitPm({
72	  equipmentId,
73	  pmPeriod,
74	  notes,
75	  sops,
76	  answers,
77	}: SubmitInput): Promise<SubmittedPm> {
78	  const form = new FormData();
79	  form.append("equipment", equipmentId);
80	  form.append("pm_period", String(pmPeriod));
81	  form.append("performed_at", new Date().toISOString());
82	  form.append("notes", notes);
83	  form.append("source", "mobile");
84	
85	  const sopRecords = sops.map((sop) => {
86	    const a = answers[sop.id] ?? EMPTY_ANSWER;
87	    return {
88	      pm_sop: sop.id,
89	      result_boolean: sop.input_type === "checkbox" ? a.ok : null,
90	      result_number:
91	        sop.input_type === "number_range" ? parseNumber(a.number) : null,
92	      result_text: sop.input_type === "text" ? a.text.trim() : null,
93	      notes: null,
94	    };
95	  });
96	  form.append("sop_records", JSON.stringify(sopRecords));
97	
98	  for (const sop of sops) {
99	    const uri = answers[sop.id]?.photoUri;
100	    // React Native's FormData takes a {uri, name, type} object for files.
101	    if (uri)
102	      form.append(`image_${sop.id}`, {
103	        uri,
104	        name: `step-${sop.id}.jpg`,
105	        type: "image/jpeg",
106	      } as never);
107	  }
108	
109	  const { data } = await api.post<SubmittedPm>("pm-records/", form, {
110	    headers: { "Content-Type": "multipart/form-data" },
111	    timeout: 120000, // photos over factory Wi-Fi
112	  });
113	  return data;
114	}

