import { api } from "@/lib/api";
import { fetchEsd, type EsdInfo, type EsdReading, type EsdSpec } from "@/lib/equipment-detail";

export { fetchEsd, type EsdInfo };

/** `POST equipments/<number>/esd/` response: the label data of the new measurement. */
export type EsdLabel = EsdReading & {
  measurement_id: string;
  equipment_number: string;
  model_name: string;
};

/**
 * Readings are typed like `5e7`, `5E+7`, `5x10^7`, `5*10^7` or `50000000`.
 * Returns null while the text is not a complete number yet.
 */
export function parseEsdValue(input: string): number | null {
  const text = input.trim().replace(/\s+/g, "").replace(",", ".");
  if (text === "") return null;
  const power = text.match(/^([0-9.]+)[x*×]10\^?([+-]?\d+)$/i);
  const value = power ? Number(power[1]) * 10 ** Number(power[2]) : Number(text);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

/** Same rule as `EsdSpec.is_within()`: an unset bound is not checked. */
export function esdPasses(spec: EsdSpec, value: number): boolean {
  return (spec.min_value == null || value >= spec.min_value) && (spec.max_value == null || value <= spec.max_value);
}

export async function saveEsdMeasurement(number: string, value: number): Promise<EsdLabel> {
  const { data } = await api.post<EsdLabel>(`equipments/${encodeURIComponent(number)}/esd/`, { value });
  return data;
}

