import { StyleSheet, Text, View } from "react-native";

import { PmsColors } from "@/constants/pms-theme";
import { formatDate, formatReading } from "@/lib/format";

type Props = {
  equipmentNumber: string;
  measuredDate: string | null;
  value: number | null;
  unit: string;
  result: "PASS" | "FAIL" | null;
  measuredBy: string | null;
};

/** On-screen look of the printed ESD label (header, QR box, five lines). Not a print template. */
export function EsdLabelPreview({ equipmentNumber, measuredDate, value, unit, result, measuredBy }: Props) {
  const rows: [string, string][] = [
    ["ID", equipmentNumber],
    ["Measured Date", formatDate(measuredDate)],
    ["Measurement", formatReading(value, unit)],
    ["Result", result ?? "—"],
    ["Measured By", measuredBy || "—"],
  ];
  return (
    <View style={styles.label}>
      <Text style={styles.header}>ESD CERTIFIED {new Date().getFullYear()}</Text>
      <View style={styles.body}>
        <View style={styles.qr}>
          <Text style={styles.qrText}>QR</Text>
        </View>
        <View style={styles.rows}>
          {rows.map(([k, v]) => (
            <Text key={k} style={styles.row} numberOfLines={1}>
              <Text style={styles.key}>{k}: </Text>
              <Text style={k === "Result" && result === "FAIL" ? styles.fail : undefined}>{v}</Text>
            </Text>
          ))}
        </View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
