import { router, useLocalSearchParams } from "expo-router";
import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, KeyboardAvoidingView, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { EsdLabelPreview } from "@/components/pms/esd-label-preview";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { errorMessage } from "@/lib/api";
import { fetchEsd, type EsdInfo } from "@/lib/equipment-detail";
import { esdPasses, parseEsdValue, saveEsdMeasurement, type EsdLabel } from "@/lib/esd";
import { formatDate, formatReading } from "@/lib/format";
import { useSession } from "@/lib/session";

export default function MeasureEsdScreen() {
  const { number } = useLocalSearchParams<{ number: string }>();
  const { member } = useSession();
  const [esd, setEsd] = useState<EsdInfo | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [input, setInput] = useState("");
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [saved, setSaved] = useState<EsdLabel | null>(null);

  useEffect(() => {
    fetchEsd(number).then(
      (data) => (data ? setEsd(data) : setLoadError("ESD measurement is not set up for this equipment.")),
      (e) => setLoadError(errorMessage(e)),
    );
  }, [number]);

  const value = parseEsdValue(input);
  const pass = esd && value !== null ? esdPasses(esd.spec, value) : null;

  async function save() {
    if (value === null || saving) return;
    setSaving(true);
    setSaveError(null);
    try {
      setSaved(await saveEsdMeasurement(number, value));
    } catch (e) {
      setSaveError(errorMessage(e));
    } finally {
      setSaving(false);
    }
  }

  function leave() {
    if (input === "" || saved) return router.back();
    Alert.alert("Discard this reading?", "The value is not saved yet.", [
      { text: "Keep working", style: "cancel" },
      { text: "Discard", style: "destructive", onPress: () => router.back() },
    ]);
  }

  // Before saving, the preview shows what the label will say; after, the saved label data.
  const preview = saved
    ? {
        measuredDate: saved.measuredDate,
        value: saved.esdValue,
        unit: saved.esdUnit,
        result: saved.result,
        measuredBy: saved.measuredBy,
      }
    : {
        measuredDate: new Date().toISOString(),
        value,
        unit: esd?.spec.unit ?? "",
        result: pass === null ? null : pass ? ("PASS" as const) : ("FAIL" as const),
        measuredBy: member?.name ?? member?.username ?? null,
      };

  return (
    <SafeAreaView style={styles.screen} edges={["top", "left", "right"]}>
      <View style={styles.bar}>
        <PmsButton title={saved ? "‹ Back" : "Cancel"} variant="secondary" onPress={leave} />
        <Text style={styles.title} numberOfLines={1}>
          Measure ESD · {number}
        </Text>
      </View>

      {esd === null ? (
        <View style={styles.center}>
          {loadError ? (
            <Text style={styles.error}>{loadError}</Text>
          ) : (
            <ActivityIndicator size="large" color={PmsColors.esd} />
          )}
        </View>
      ) : (
        <KeyboardAvoidingView style={styles.flex} behavior="height">
          <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
            <View style={styles.main}>
              <View style={styles.card}>
                <Text style={styles.label}>Spec</Text>
                <Text style={styles.spec}>{esd.spec.spec_label || esd.spec.name}</Text>
                <Text style={styles.muted}>
                  Last reading:{" "}
                  {esd.latest
                    ? `${formatReading(esd.latest.esdValue, esd.latest.esdUnit)} · ${esd.latest.result} · ${formatDate(esd.latest.measuredDate)}`
                    : "not measured yet"}
                </Text>
              </View>

              <View style={styles.card}>
                <Text style={styles.label}>Reading ({esd.spec.unit})</Text>
                <View style={styles.row}>
                  <TextInput
                    value={input}
                    onChangeText={(t) => {
                      setInput(t);
                      setSaveError(null);
                    }}
                    editable={!saved}
                    placeholder="e.g. 5e7"
                    placeholderTextColor={PmsColors.textSecondary}
                    autoCapitalize="none"
                    autoCorrect={false}
                    keyboardType="default"
                    returnKeyType="done"
                    onSubmitEditing={save}
                    maxFontSizeMultiplier={1.2}
                    style={styles.input}
                  />
                  {pass !== null && (
                    <View style={[styles.verdict, { backgroundColor: pass ? PmsColors.onTime : PmsColors.overdue }]}>
                      <Text style={styles.verdictText}>{pass ? "PASS" : "FAIL"}</Text>
                    </View>
                  )}
                </View>
                <Text style={styles.muted}>
                  {value !== null
                    ? `= ${formatReading(value, esd.spec.unit)}`
                    : input.trim() !== ""
                      ? "Not a number. Use 5e7, 5x10^7 or 50000000."
                      : "Type the meter reading. 5e7 means 5 × 10⁷."}
                </Text>
              </View>

              {saveError && <Text style={styles.error}>{saveError}</Text>}

              {saved ? (
                <View style={styles.savedBox}>
                  <Text style={styles.savedText}>Saved.</Text>
                  <PmsButton title="Print label (coming soon)" variant="esd" disabled onPress={() => {}} />
                  <PmsButton title="Back to equipment" variant="secondary" onPress={() => router.back()} />
                </View>
              ) : (
                <PmsButton title="Save measurement" variant="esd" onPress={save} disabled={value === null} loading={saving} />
              )}
            </View>

            <View style={styles.side}>
              <Text style={styles.label}>Label preview</Text>
              <EsdLabelPreview equipmentNumber={number} {...preview} />
            </View>
          </ScrollView>
        </KeyboardAvoidingView>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
  flex: { flex: 1 },
  bar: {
    flexDirection: "row",
    alignItems: "center",
    gap: PmsSizes.gap,
    padding: PmsSizes.gap,
    paddingHorizontal: PmsSizes.pad,
    backgroundColor: PmsColors.surface,
    borderBottomWidth: 6,
    borderBottomColor: PmsColors.esd,
  },
  title: { flex: 1, fontSize: 24, fontWeight: "700", color: PmsColors.text },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: PmsSizes.pad },
  content: { flexDirection: "row", flexWrap: "wrap", gap: PmsSizes.pad, padding: PmsSizes.pad },
  main: { flexGrow: 3, flexBasis: 420, gap: PmsSizes.gap },
  side: { flexGrow: 2, flexBasis: 320, gap: 8 },
  card: {
    backgroundColor: PmsColors.surface,
    borderRadius: PmsSizes.radius,
    borderWidth: 1,
    borderColor: PmsColors.border,
    padding: PmsSizes.gap + 4,
    gap: 10,
  },
  label: { fontSize: 15, fontWeight: "700", color: PmsColors.textSecondary },
  spec: { fontSize: 24, fontWeight: "800", color: PmsColors.text },
  muted: { fontSize: 15, color: PmsColors.textSecondary },
  row: { flexDirection: "row", alignItems: "center", gap: PmsSizes.gap },
  input: {
    flex: 1,
    minHeight: 76,
    paddingHorizontal: 16,
    borderWidth: 2,
    borderColor: PmsColors.border,
    borderRadius: PmsSizes.radius,
    backgroundColor: PmsColors.surface,
    fontSize: 36,
    fontWeight: "800",
    color: PmsColors.text,
  },
  verdict: { paddingHorizontal: 22, paddingVertical: 16, borderRadius: PmsSizes.radius },
  verdictText: { fontSize: 26, fontWeight: "800", color: PmsColors.textOnPrimary },
  error: { fontSize: 16, color: PmsColors.danger },
  savedBox: { gap: PmsSizes.gap },
  savedText: { fontSize: 20, fontWeight: "700", color: PmsColors.onTime },
});

