        <KeyboardAvoidingView style={styles.flex} behavior="height">
          <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
            <View style={styles.main}>
              <View style={styles.card}>
                <Text style={styles.label}>Spec</Text>
                <Text style={styles.spec}>{esd.spec.spec_label || esd.spec.name}</Text>
                <Text style={styles.muted}>
                  Last reading:{" "}
                  {esd.latest
                    ? `${formatReading(esd.latest.esdValue, esd.latest.esdUnit)} · ${esd.latest.result} · ${formatDate(esd.latest.measuredDate)}`
                    : "not measured yet"}
                </Text>
              </View>

              <View style={styles.card}>
                <Text style={styles.label}>Reading ({esd.spec.unit})</Text>
                <View style={styles.row}>
                  <TextInput
                    value={input}
                    onChangeText={(t) => {
                      setInput(t);
                      setSaveError(null);
                    }}
                    editable={!saved}
                    placeholder="e.g. 5e7"
                    placeholderTextColor={PmsColors.textSecondary}
                    autoCapitalize="none"
                    autoCorrect={false}
                    keyboardType="default"
                    returnKeyType="done"
                    onSubmitEditing={save}
                    maxFontSizeMultiplier={1.2}
                    style={styles.input}
                  />
                  {pass !== null && (
                    <View style={[styles.verdict, { backgroundColor: pass ? PmsColors.onTime : PmsColors.overdue }]}>
                      <Text style={styles.verdictText}>{pass ? "PASS" : "FAIL"}</Text>
                    </View>
                  )}
                </View>
                <Text style={styles.muted}>
                  {value !== null
                    ? `= ${formatReading(value, esd.spec.unit)}`
                    : input.trim() !== ""
                      ? "Not a number. Use 5e7, 5x10^7 or 50000000."
                      : "Type the meter reading. 5e7 means 5 × 10⁷."}
                </Text>
              </View>

              {saveError && <Text style={styles.error}>{saveError}</Text>}

              {saved ? (
                <View style={styles.savedBox}>
                  <Text style={styles.savedText}>Saved.</Text>
                  <PmsButton title="Print label (coming soon)" variant="esd" disabled onPress={() => {}} />
                  <PmsButton title="Back to equipment" variant="secondary" onPress={() => router.back()} />
                </View>
              ) : (
                <PmsButton title="Save measurement" variant="esd" onPress={save} disabled={value === null} loading={saving} />
              )}
            </View>

            <View style={styles.side}>
              <Text style={styles.label}>Label preview</Text>
              <EsdLabelPreview equipmentNumber={number} {...preview} />
            </View>
          </ScrollView>
        </KeyboardAvoidingView>
      )}
    </SafeAreaView>
  );
}

