import { useEffect, useRef, useState, type ReactNode } from "react";
import { AppState, Modal, StyleSheet, Text, View } from "react-native";

import { PmsButton } from "@/components/pms/button";
import { IDLE_WARNING_SECONDS } from "@/constants/config";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { useSession } from "@/lib/session";

const CHECK_EVERY_MS = 1000;

/**
 * Signs the member out after `idleMinutes` without a touch — one tablet is shared by a shift.
 * Time is measured with the clock, so time spent in the background or with the screen off counts too.
 */
export function IdleGuard({ children }: { children: ReactNode }) {
  const { member, idleMinutes, signOut } = useSession();
  const lastTouch = useRef(Date.now());
  const [secondsLeft, setSecondsLeft] = useState<number | null>(null);
  const signedIn = member !== null;

  useEffect(() => {
    if (!signedIn) return;
    lastTouch.current = Date.now();
    const limitMs = idleMinutes * 60_000;

    function check() {
      const left = Math.ceil((limitMs - (Date.now() - lastTouch.current)) / 1000);
      if (left <= 0) {
        setSecondsLeft(null);
        signOut();
      } else {
        setSecondsLeft(left <= IDLE_WARNING_SECONDS ? left : null);
      }
    }

    const timer = setInterval(check, CHECK_EVERY_MS);
    // Timers pause in the background; check as soon as the app is back.
    const sub = AppState.addEventListener("change", (state) => {
      if (state === "active") check();
    });
    return () => {
      clearInterval(timer);
      sub.remove();
      setSecondsLeft(null);
    };
  }, [signedIn, idleMinutes, signOut]);

  function touched() {
    lastTouch.current = Date.now();
    return false; // only watch the touch; let the screen underneath handle it
  }

  function stayIn() {
    lastTouch.current = Date.now();
    setSecondsLeft(null);
  }

  return (
    <View style={styles.flex} onStartShouldSetResponderCapture={touched} onMoveShouldSetResponderCapture={touched}>
      {children}
      <Modal visible={secondsLeft !== null} transparent animationType="fade" supportedOrientations={["landscape"]}>
        <View style={styles.backdrop}>
          <View style={styles.box}>
            <Text style={styles.title}>Still there?</Text>
            <Text style={styles.text}>
              {member?.name ?? member?.username} will be signed out in {secondsLeft} s.
            </Text>
            <View style={styles.row}>
              <PmsButton title="Sign out now" variant="secondary" onPress={signOut} style={styles.flex} />
              <PmsButton title="I'm still here" onPress={stayIn} style={styles.flex} />
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  backdrop: { flex: 1, backgroundColor: "rgba(15,23,42,0.6)", alignItems: "center", justifyContent: "center" },
  box: {
    width: "90%",
    maxWidth: 520,
    backgroundColor: PmsColors.surface,
    borderRadius: PmsSizes.radius,
    padding: PmsSizes.pad,
    gap: PmsSizes.gap,
  },
  title: { fontSize: 28, fontWeight: "800", color: PmsColors.text },
  text: { fontSize: 18, color: PmsColors.text },
  row: { flexDirection: "row", gap: PmsSizes.gap },
});

