export const ESC = "\u001B";

/** Job start + media setup, identical in every PMS-Android template. */
const START =
  `${ESC}A\n` +
  `${ESC}A3V+00000H+0000${ESC}CS4${ESC}#F5${ESC}A1V00719H0440\n` +
  `${ESC}A${ESC}PS${ESC}WK12_06_2019_Infor\n`;

/** Print one copy, end of job. */
const END = `${ESC}Q1\n${ESC}Z`;

/** Horizontal rule under the header (`FW04` = 4-dot line, `H0365` = 365 dots long). */
function line(h: number, v: number, length = 365): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}FW04H${pad(length, 4)}\n`;
}

/** Large header text (SATO0 TrueType, 22 × 26). */
function header(h: number, v: number, text: string): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}P02${ESC}RH0,SATO0.ttf,1,022,026,${text}\n`;
}

/** Body text line (built-in font, 17 × 21). */
function text(h: number, v: number, value: string): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}P02${ESC}RDB@0,017,021,${value}\n`;
}

/** QR code, model 2, error level M, cell size `cell`. Data length is 4 digits, as SBPL expects. */
function qr(h: number, v: number, data: string, cell = 6): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}2D30,M,${pad(cell, 2)},1,0${ESC}DN${pad(data.length, 4)},${data}\n`;
}

function pad(n: number, width: number): string {
  return String(n).padStart(width, "0");
}

/** Cut to fit the label width (the text column holds about `max` characters). */
export function fit(value: string | null | undefined, max: number): string {
  const v = (value ?? "").trim();
  return v.length > max ? `${v.slice(0, max - 3)}...` : v;
}

/** PMS-Android `formatShortName`. */
export function shortName(full: string | null | undefined): string {
  const parts = (full ?? "").trim().split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return `${parts[0]} ${parts[1].slice(0, 3)}.`;
  return fit(parts[0], 15);
}

// ── ESD label ──────────────────────────────────────────────────────────────────

export type EsdLabelData = {
  equipmentNumber: string;
  /** DD/MM/YYYY */
  measuredDate: string;
  /** Already formatted, e.g. "5.0e+7 Ω" */
  measurement: string;
  result: "PASS" | "FAIL";
  measuredBy: string;
};

