export const ESC = "\u001B";

/** Job start + media setup, identical in every PMS-Android template. */
const START =
  `${ESC}A\n` +
  `${ESC}A3V+00000H+0000${ESC}CS4${ESC}#F5${ESC}A1V00719H0440\n` +
  `${ESC}A${ESC}PS${ESC}WK12_06_2019_Infor\n`;

/** Print one copy, end of job. */
const END = `${ESC}Q1\n${ESC}Z`;

/** Horizontal rule under the header (`FW04` = 4-dot line, `H0365` = 365 dots long). */
function line(h: number, v: number, length = 365): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}FW04H${pad(length, 4)}\n`;
}

/** Large header text (SATO0 TrueType, 22 × 26 unless given). */
function header(h: number, v: number, text: string, w = 22, ht = 26): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}P02${ESC}RH0,SATO0.ttf,1,${pad(w, 3)},${pad(ht, 3)},${text}\n`;
}

/** Body text line (built-in font, 17 × 21 unless given). */
function text(h: number, v: number, value: string, w = 17, ht = 21): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}P02${ESC}RDB@0,${pad(w, 3)},${pad(ht, 3)},${value}\n`;
}

/** QR code, model 2, error level M, cell size `cell`. Data length is 4 digits, as SBPL expects. */
function qr(h: number, v: number, data: string, cell = 6): string {
  return `${ESC}%0${ESC}H${pad(h, 4)}${ESC}V${pad(v, 5)}${ESC}2D30,M,${pad(cell, 2)},1,0${ESC}DN${pad(data.length, 4)},${data}\n`;
}

/** Body lines at H0190, one every `step` dots — the right-hand column of every PM layout. */
function rows(top: number, lines: string[], step = 30): string {
  return lines.map((l, i) => text(190, top + i * step, l)).join("");
}

function pad(n: number, width: number): string {
  return String(n).padStart(width, "0");
}

/** Cut to fit the label width (the text column holds about `max` characters). */
export function fit(value: string | null | undefined, max: number): string {
  const v = (value ?? "").trim();
  return v.length > max ? `${v.slice(0, max - 3)}...` : v;
}

/** PMS-Android `formatShortName`. */
export function shortName(full: string | null | undefined): string {
  const parts = (full ?? "").trim().split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return `${parts[0]} ${parts[1].slice(0, 3)}.`;
  return fit(parts[0], 15);
}

/** Description over three lines: 15, 20, 20 characters (PMS-Android NPI3 / NPI5). */
function detailLines(detail: string | null | undefined): [string, string, string] {
  const d = (detail ?? "").trim();
  return [d.slice(0, 15), d.slice(15, 35), d.slice(35, 55)];
}

/** "Line A; Box 3" → ["Line A", "Box 3"] (PMS-Android NPI1 / NPI2 keep both in `location`). */
function locationAndBox(location: string | null | undefined): [string, string] {
  const [loc = "", box = ""] = (location ?? "").split(";").map((s) => s.trim());
  return [loc, box];
}

// ── ESD label ──────────────────────────────────────────────────────────────────

export type EsdLabelData = {
  equipmentNumber: string;
  /** DD/MM/YYYY */
  measuredDate: string;
  /** Value only, no unit, e.g. "5.0e+7" */
  measurement: string;
  result: "PASS" | "FAIL";
  measuredBy: string;
};

/** `ESD CERTIFIED <year>` header, QR of the equipment number, five lines. */
export function buildEsdLabel(d: EsdLabelData, year = new Date().getFullYear()): string {
  return (
    START +
    line(25, 50) +
    header(95, 18, `ESD CERTIFIED ${year}`) +
    qr(25, 65, d.equipmentNumber) +
    text(165, 70, `Equip No: ${fit(d.equipmentNumber, 20)}`) +
    text(165, 100, `Measured Date: ${d.measuredDate}`) +
    text(165, 130, `Measurement: ${fit(d.measurement, 13)}`) +
    text(165, 160, `Result: ${d.result}`) +
    text(165, 190, `Measured By: ${fit(d.measuredBy, 16)}`) +
    END
  );
}

// ── PM labels: every equipment format of PMS-Android `FormatLabelManager` ─────────

/** Equipment data a PM label can print. Legacy `Shape` field in brackets. */
export type PmLabelData = {
  equipmentNumber: string; // machine_tag
  model: string | null; // modelName
  partNumber: string | null; // partNumber ("Number")
  serialNumber: string | null; // equipmentSerialNumber ("SN") — no field in PMS-PLUS yet
  location: string | null;
  pic: string | null; // incharge ("UserName" / Owner)
  description: string | null; // description ("Detail")
  /** Section text in the Tooling header; legacy used the selected section (category). */
  dept: string | null;
  /** DD/MM/YYYY or "—" */
  nextPmDate: string;
  lastPmDate: string;
};

export type PmLabelFormat = {
  /** Stable id, to be stored per Category on the backend. Never rename. */
  id: string;
  /** Name shown when choosing a format. */
  name: string;
  /** PMS-Android method it was taken from. */
  legacy: string;
  build: (d: PmLabelData) => string;
};

/** Number header on the left, a word on the right (e.g. "PMS"), rule, QR at H0045 V0085. */
function numberHeader(d: PmLabelData, right: string, qrCell = 6): string {
  return (
    line(35, 55) +
    header(45, 18, fit(d.equipmentNumber, 20)) +
    header(350, 18, right) +
    qr(45, 85, d.equipmentNumber, qrCell)
  );
}

/** "CNBU / NPI/ME" block of the NPI3–5 layouts, printed twice 1 dot apart for a bold look. */
function npiBadge(): string {
  return (
    text(336, 15, "CNBU", 21, 22) +
    text(330, 35, "NPI/ME", 21, 22) +
    text(337, 15, "CNBU", 21, 22) +
    text(331, 35, "NPI/ME", 21, 22)
  );
}

function npiHeader(d: PmLabelData): string {
  return line(35, 55) + header(40, 18, fit(d.equipmentNumber, 20)) + qr(45, 85, d.equipmentNumber);
}

export const PM_LABEL_FORMATS: PmLabelFormat[] = [
  {
    id: "machine",
    name: "Machine",
    legacy: "stringLabelMachine",
    build: (d) =>
      START +
      line(35, 55) +
      header(45, 18, "Preventive Maintenance System") +
      qr(45, 85, d.equipmentNumber, 5) +
