import { api } from "@/lib/api";

export type LabelType = "pm" | "esd";

/** `GET equipments/<number>/label/` — the backend builds the SATO commands for web and tablet alike. */
export type LabelResponse = {
  type: LabelType;
  /** PM layout id chosen by the equipment's category (`fixture`, `tooling`, `machine`), or `esd`. */
  format: string;
  sbpl: string;
};

export async function fetchLabel(number: string, type: LabelType, layout?: string): Promise<LabelResponse> {
  const { data } = await api.get<LabelResponse>(`equipments/${encodeURIComponent(number)}/label/`, {
    params: { type, ...(layout ? { layout } : {}) },
  });
  return data;
}

/** Bytes to write to the printer socket (UTF-8, like Java `getBytes()` on PMS-Android). */
export function toPrinterBytes(sbpl: string): Uint8Array {
  return new TextEncoder().encode(sbpl);
}

