});

const fmtDate = (d) => (d ? dayjs(d).format('DD/MM/YYYY') : '');

const InfoRow = ({ label, value }) => (
  <div className="flex text-xs">
    <span className="text-slate-500 shrink-0">{label}:&nbsp;</span>
    <span className="font-medium text-slate-800 truncate">{value || '—'}</span>
  </div>
);

function PrintEsdLabelDialog({ open, onClose, equipmentNumber: initialEquipmentNumber }) {

  const [equipmentNumber, setEquipmentNumber] = useState(initialEquipmentNumber || '');
  const [fields, setFields] = useState(buildInitialFields);
  const [loaded, setLoaded] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState('');
  const [printing, setPrinting] = useState(false);
  const [spec, setSpec] = useState(null);
  const [reading, setReading] = useState('');
  const [saving, setSaving] = useState(false);

  const applyLabel = (d, number) => {
    setFields((prev) => ({
      ...prev,
      equipment_number: d.equipment_number || number,
      measuredDate: d.measuredDate || '',
      esdValue: d.esdValue != null ? String(d.esdValue) : '',
      esdUnit: d.esdUnit || '',
      result: d.result || '-',
      measuredBy: d.measuredBy || '',
    }));
    setLoaded(true);
  };

  const resetState = () => {
    setEquipmentNumber('');
    setFields(buildInitialFields());
    setLoaded(false);
    setLoadError('');
    setSpec(null);
    setReading('');
  };

  const onEqNumberChange = (value) => {
    setEquipmentNumber(value);
    if (loaded || spec) {
      setLoaded(false);
      setSpec(null);
      setFields(buildInitialFields());
    }
    if (loadError) setLoadError('');
  };

  const loadEsdData = async () => {
    const number = equipmentNumber.trim();
    if (!number) {
      toast.error("Enter an equipment number first.");
      return;
    }
    setLoading(true);
    setLoadError('');
    try {
      const res = await axios.get(
        `${API_EQUIPMENTS}${encodeURIComponent(number)}/esd/`,
        authConfig(),
      );
      setSpec(res.data.spec);
      if (res.data.latest) {
        applyLabel(res.data.latest, number);
      } else {
        setLoaded(false);
        setFields({ ...buildInitialFields(), equipment_number: res.data.equipment_number || number });
      }
    } catch (err) {
      setLoaded(false);
      setSpec(null);
      const status = err.response?.status;
      const code = err.response?.data?.code;
      const detail = err.response?.data?.detail;
      setLoadError(
        status === 404
          ? `Equipment "${number}" not found.`
          : (ERROR_MESSAGES[code] || detail || 'Failed to load ESD data.')
      );
    } finally {
      setLoading(false);
    }
  };

  const saveReading = async () => {
    const value = Number(reading.trim());
    if (!reading.trim() || !Number.isFinite(value)) {
      toast.error("Enter the measured value as a number (e.g. 5e7).");
      return;
    }
    setSaving(true);
    try {
      const number = equipmentNumber.trim();
      const res = await axios.post(
        `${API_EQUIPMENTS}${encodeURIComponent(number)}/esd/`,
        { value },
        authConfig(),
      );
      applyLabel(res.data, number);
      setReading('');
      toast.success(`Measurement saved — ${res.data.result}.`);
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to save the measurement.');
    } finally {
      setSaving(false);
    }
  };

  const printFn = async () => {
    if (printing || !loaded) return;

    const missing = ['equipment_number', 'measuredDate', 'esdValue', 'measuredBy']
      .find((k) => !String(fields[k] ?? '').trim()) || (fields.result === '-' ? 'result' : null);
    if (missing) {
      toast.error("The ESD measurement is incomplete — cannot print this label.");
      return;
    }

    setPrinting(true);
    const toastId = toast.loading("Sending to printer...");
    try {
      const result = await printEsdLabel({
        header: fields.header,
        equipment_number: fields.equipment_number,
        measuredDate: fmtDate(fields.measuredDate),
        esdValue: fields.esdValue,
        esdUnit: fields.esdUnit,
        result: fields.result,
        measuredBy: fields.measuredBy,
      });

      if (result.ok) {
        toast.success(`Printed to ${result.printer || "printer"}.`, { id: toastId });
      } else if (result.error === "BRIDGE_UNREACHABLE") {
        toast.error(
          "Print bridge not reachable. Make sure the PMS Middleware app is running on this device.",
          { id: toastId }
        );
      } else {
        toast.error(`Print failed: ${result.error}`, { id: toastId });
      }
    } catch (err) {
      toast.error(`Print failed: ${err.message || "unknown error"}`, { id: toastId });
    } finally {
      setPrinting(false);
    }
  };

  const handleOnClose = () => {
    resetState();
    onClose();
  };

