package expo.modules.satoprinter

import android.Manifest
import android.annotation.SuppressLint
import android.bluetooth.BluetoothAdapter
import android.bluetooth.BluetoothManager
import android.bluetooth.BluetoothSocket
import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import expo.modules.kotlin.exception.CodedException
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import java.io.IOException
import java.util.UUID

/**
 * Prints raw SATO SBPL to a paired printer over Bluetooth Classic SPP — what PMS-Android's
 * bluetoothActivity does. Each print opens the socket, writes, and closes it again, so there is
 * no connection to keep alive between labels.
 */
class SatoPrinterModule : Module() {
  // The well-known Serial Port Profile UUID; SATO PW208NX and the legacy app use it.
  private val sppUuid: UUID = UUID.fromString("00001101-0000-1000-8000-00805F9B34FB")

  private val context: Context
    get() = appContext.reactContext ?: throw CodedException("NO_CONTEXT", "Android context is not available.", null)

  private val adapter: BluetoothAdapter?
    get() = (context.getSystemService(Context.BLUETOOTH_SERVICE) as? BluetoothManager)?.adapter

  override fun definition() = ModuleDefinition {
    Name("SatoPrinter")

    /** False when the tablet has no Bluetooth or it is switched off. */
    Function("isEnabled") {
      adapter?.isEnabled == true
    }

    /** Devices already paired in Android settings: [{ name, address }]. */
    AsyncFunction("getPairedPrinters") {
      val bt = requireAdapter()
      @SuppressLint("MissingPermission") // checked in requireAdapter()
      val devices = bt.bondedDevices.orEmpty()
      return@AsyncFunction devices
        .map { mapOf("name" to (it.name ?: it.address), "address" to it.address) }
        .sortedBy { (it["name"] ?: "").lowercase() }
    }

    /** Sends `data` (SBPL text) as UTF-8 bytes, like Java `getBytes()` in the legacy app. */
    AsyncFunction("print") Coroutine { address: String, data: String ->
      val bt = requireAdapter()
      withContext(Dispatchers.IO) {
        @SuppressLint("MissingPermission")
        val device = try {
          bt.getRemoteDevice(address)
        } catch (e: IllegalArgumentException) {
          throw CodedException("BAD_ADDRESS", "Not a Bluetooth address: $address", e)
        }
        @SuppressLint("MissingPermission")
        bt.cancelDiscovery() // discovery slows down or breaks connect()

        val socket = connect(device)
        try {
          socket.outputStream.write(data.toByteArray(Charsets.UTF_8))
          socket.outputStream.flush()
          // Closing straight away can cut the last bytes before the printer reads them.
          delay(800)
        } catch (e: IOException) {
          throw CodedException("WRITE_FAILED", "Lost the printer while sending: ${e.message}", e)
        } finally {
          try { socket.close() } catch (_: IOException) {}
        }
      }
      return@Coroutine null
    }
  }

  @SuppressLint("MissingPermission")
  private fun connect(device: android.bluetooth.BluetoothDevice): BluetoothSocket {
    // Secure RFCOMM first (what the legacy app uses), then insecure, which some printers need.
    val attempts = listOf<() -> BluetoothSocket>(
      { device.createRfcommSocketToServiceRecord(sppUuid) },
      { device.createInsecureRfcommSocketToServiceRecord(sppUuid) },
    )
    var last: IOException? = null
    for (create in attempts) {
      val socket = create()
      try {
        socket.connect()
        return socket
      } catch (e: IOException) {
        last = e
        try { socket.close() } catch (_: IOException) {}
      }
    }
    throw CodedException(
      "CONNECT_FAILED",
      "Could not connect to the printer. Check it is on, in range and not connected to another device.",
      last,
    )
  }

  private fun requireAdapter(): BluetoothAdapter {
    val bt = adapter ?: throw CodedException("NO_BLUETOOTH", "This device has no Bluetooth.", null)
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
      context.checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED
    ) {
      throw CodedException("NO_PERMISSION", "Allow PMS+ to use Nearby devices (Bluetooth) to print.", null)
    }
    if (!bt.isEnabled) throw CodedException("BLUETOOTH_OFF", "Turn on Bluetooth to print.", null)
    return bt
  }
}

