import { requireOptionalNativeModule } from "expo-modules-core";
import { PermissionsAndroid, Platform } from "react-native";

export type PairedPrinter = { name: string; address: string };

type SatoPrinterNative = {
  isEnabled(): boolean;
  getPairedPrinters(): Promise<PairedPrinter[]>;
  print(address: string, data: string): Promise<null>;
};

// Null where the native module is missing (web, Expo Go, or a build made before the module was added).
const native = requireOptionalNativeModule<SatoPrinterNative>("SatoPrinter");

export function isAvailable(): boolean {
  return native !== null;
}

export function isBluetoothOn(): boolean {
  return native?.isEnabled() ?? false;
}

/** Android 12+ asks for "Nearby devices" at run time; older versions grant it at install. */
export async function ensurePermission(): Promise<boolean> {
  if (Platform.OS !== "android" || Platform.Version < 31) return true;
  const result = await PermissionsAndroid.request(PermissionsAndroid.PERMISSIONS.BLUETOOTH_CONNECT);
  return result === PermissionsAndroid.RESULTS.GRANTED;
}

function requireNative(): SatoPrinterNative {
  if (!native) throw new Error("Printing needs the PMS+ development build with the printer module (npx expo run:android).");
  return native;
}

export async function getPairedPrinters(): Promise<PairedPrinter[]> {
  return requireNative().getPairedPrinters();
}

/** Sends SBPL text to the printer at `address` (opens, writes, closes). */
export async function print(address: string, sbpl: string): Promise<void> {
  await requireNative().print(address, sbpl);
}

