import * as SecureStore from "expo-secure-store";

import * as SatoPrinter from "@/modules/sato-printer";
import { api } from "@/lib/api";

export type LabelType = "pm" | "esd";

/** `GET equipments/<number>/label/` — the backend builds the SATO commands for web and tablet alike. */
export type LabelResponse = {
  type: LabelType;
  /** PM layout id chosen by the equipment's category (`fixture`, `tooling`, `machine`), or `esd`. */
  format: string;
  sbpl: string;
};

export async function fetchLabel(number: string, type: LabelType): Promise<LabelResponse> {
  const { data } = await api.get<LabelResponse>(`equipments/${encodeURIComponent(number)}/label/`, {
    params: { type },
  });
  return data;
}

// ── The tablet's printer (one per tablet, kept across sign-outs) ────────────────

const PRINTER_KEY = "pms.printer";

export async function getSavedPrinter(): Promise<SatoPrinter.PairedPrinter | null> {
  const raw = await SecureStore.getItemAsync(PRINTER_KEY);
  return raw ? (JSON.parse(raw) as SatoPrinter.PairedPrinter) : null;
}

export async function savePrinter(printer: SatoPrinter.PairedPrinter | null): Promise<void> {
  if (printer) await SecureStore.setItemAsync(PRINTER_KEY, JSON.stringify(printer));
  else await SecureStore.deleteItemAsync(PRINTER_KEY);
}

/** Thrown when no printer is chosen yet, so the screen can open the printer picker. */
export class NoPrinterError extends Error {
  constructor() {
    super("Choose a printer first.");
  }
}

/** Gets the label from the backend and sends it to the saved printer. Resolves with the printer name. */
export async function printLabel(number: string, type: LabelType): Promise<string> {
  const printer = await getSavedPrinter();
  if (!printer) throw new NoPrinterError();
  if (!(await SatoPrinter.ensurePermission())) {
    throw new Error("Allow PMS+ to use Nearby devices (Bluetooth) to print.");
  }
  const { sbpl } = await fetchLabel(number, type);
  await SatoPrinter.print(printer.address, sbpl);
  return printer.name;
}

