import { router } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, Linking, Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { PmsButton } from "@/components/pms/button";
import { PmsColors, PmsSizes } from "@/constants/pms-theme";
import { errorMessage } from "@/lib/api";
import { getSavedPrinter, savePrinter } from "@/lib/print-label";
import * as SatoPrinter from "../../modules/sato-printer";

/** Pick the label printer from the devices paired in Android Bluetooth settings. */
export default function PrinterScreen() {
  const [printers, setPrinters] = useState<SatoPrinter.PairedPrinter[] | null>(null);
  const [selected, setSelected] = useState<SatoPrinter.PairedPrinter | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      setSelected(await getSavedPrinter());
      if (!SatoPrinter.isAvailable()) {
        throw new Error("This build has no printer support. Rebuild the app with npx expo run:android.");
      }
      if (!(await SatoPrinter.ensurePermission())) {
        throw new Error("Allow PMS+ to use Nearby devices (Bluetooth) to find the printer.");
      }
      if (!SatoPrinter.isBluetoothOn()) throw new Error("Bluetooth is off. Turn it on, then tap Refresh.");
      setPrinters(await SatoPrinter.getPairedPrinters());
    } catch (e) {
      setPrinters([]);
      setError(errorMessage(e));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function choose(p: SatoPrinter.PairedPrinter) {
    await savePrinter(p);
    setSelected(p);
  }

  return (
    <SafeAreaView style={styles.screen}>
      <View style={styles.bar}>
        <PmsButton title="‹ Back" variant="secondary" onPress={() => router.back()} />
        <Text style={styles.title}>Label printer</Text>
        <PmsButton title="Refresh" variant="secondary" onPress={load} loading={loading} />
      </View>

      <ScrollView contentContainerStyle={styles.content}>
        <Text style={styles.hint}>
          Pair the SATO printer in Android Settings → Bluetooth first (PIN is usually 0000), then choose it here.
          The choice is kept on this tablet.
        </Text>
        <PmsButton
          title="Open Bluetooth settings"
          variant="secondary"
          onPress={() => Linking.sendIntent("android.settings.BLUETOOTH_SETTINGS")}
        />

        {error && <Text style={styles.error}>{error}</Text>}
        {printers === null ? (
          <ActivityIndicator size="large" color={PmsColors.primary} />
        ) : printers.length === 0 && !error ? (
          <Text style={styles.hint}>No paired devices yet.</Text>
        ) : (
          printers.map((p) => {
            const on = selected?.address === p.address;
            return (
              <Pressable
                key={p.address}
                accessibilityRole="radio"
                accessibilityState={{ selected: on }}
                onPress={() => choose(p)}
                style={({ pressed }) => [styles.row, on && styles.rowOn, pressed && styles.rowPressed]}>
                <View style={styles.flex}>
                  <Text style={styles.name}>{p.name}</Text>
                  <Text style={styles.address}>{p.address}</Text>
                </View>
                {on && <Text style={styles.check}>✓ In use</Text>}
              </Pressable>
            );
          })
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: PmsColors.background },
  flex: { flex: 1 },
  bar: {
    flexDirection: "row",
    alignItems: "center",
    gap: PmsSizes.gap,
    padding: PmsSizes.gap,
    paddingHorizontal: PmsSizes.pad,
    backgroundColor: PmsColors.surface,
    borderBottomWidth: 1,
    borderBottomColor: PmsColors.border,
  },
  title: { flex: 1, fontSize: 24, fontWeight: "700", color: PmsColors.text },
  content: { padding: PmsSizes.pad, gap: PmsSizes.gap, width: "100%", maxWidth: 760, alignSelf: "center" },
  hint: { fontSize: 16, color: PmsColors.textSecondary },
  error: { fontSize: 16, color: PmsColors.danger },
  row: {
    flexDirection: "row",
    alignItems: "center",
    minHeight: 72,
    padding: PmsSizes.gap,
    borderRadius: PmsSizes.radius,
    borderWidth: 2,
    borderColor: PmsColors.border,
    backgroundColor: PmsColors.surface,
  },
  rowOn: { borderColor: PmsColors.primary },
  rowPressed: { backgroundColor: "#E0F0FA" },
  name: { fontSize: 20, fontWeight: "700", color: PmsColors.text },
  address: { fontSize: 14, color: PmsColors.textSecondary },
  check: { fontSize: 16, fontWeight: "700", color: PmsColors.primary },
});

