import { router } from "expo-router";
import { useState } from "react";
import { Alert } from "react-native";

import { PmsButton } from "@/components/pms/button";
import { errorMessage } from "@/lib/api";
import { NoPrinterError, printLabel, type LabelType } from "@/lib/print-label";

type Props = {
  number: string;
  type: LabelType;
  title: string;
  variant?: "primary" | "secondary" | "esd";
};

/** Prints the backend-built label to this tablet's printer; offers the printer picker when none is set. */
export function PrintLabelButton({ number, type, title, variant = "secondary" }: Props) {
  const [busy, setBusy] = useState(false);

  async function onPress() {
    setBusy(true);
    try {
      const printer = await printLabel(number, type);
      Alert.alert("Printed", `Label sent to ${printer}.`);
    } catch (e) {
      if (e instanceof NoPrinterError) {
        Alert.alert("No printer chosen", "Choose the label printer for this tablet.", [
          { text: "Cancel", style: "cancel" },
          { text: "Choose printer", onPress: () => router.push("/printer") },
        ]);
      } else {
        Alert.alert("Print failed", errorMessage(e), [
          { text: "OK", style: "cancel" },
          { text: "Printer settings", onPress: () => router.push("/printer") },
        ]);
      }
    } finally {
      setBusy(false);
    }
  }

  return <PmsButton title={title} variant={variant} onPress={onPress} loading={busy} />;
}

