      if (e instanceof NoPrinterError) {
        Alert.alert("No printer chosen", "Choose the label printer for this tablet.", [
          { text: "Cancel", style: "cancel" },
          { text: "Choose printer", onPress: () => router.push("/printer") },
        ]);
      } else {
        Alert.alert("Print failed", errorMessage(e), [
          { text: "OK", style: "cancel" },
          { text: "Printer settings", onPress: () => router.push("/printer") },
        ]);
      }
    } finally {
      setBusy(false);
    }
  }

  return <PmsButton title={title} variant={variant} onPress={onPress} loading={busy} />;
}

